                        <span class="tag">{{ tag }}</span>
                        {% endfor %}
                    </div>
                    {% endif %}

                    <div class="availability">
                        {% if product.in_stock %}
                        <span class="in-stock">In Stock ({{ product.stock_quantity }} units)</span>
                        {% else %}
                        <span class="out-of-stock">Out of Stock</span>
                        {% endif %}
                    </div>

