from dataclasses import dataclass, field
from typing import Optional


@dataclass
class Room:
    id: str
    name: str
    description: str
    connections: dict[str, str]
    items: list[str] = field(default_factory=list)
    npcs: list[str] = field(default_factory=list)


@dataclass
class Item:
    id: str
    name: str
    description: str
    can_take: bool


@dataclass
class NPC:
    id: str
    name: str
    description: str
    dialogue: dict[str, str]  # dialogue tree: node_id -> text
    initial_state: dict[str, str] = field(default_factory=dict)


@dataclass
class GameState:
    player_location: str
    inventory: list[str] = field(default_factory=list)
    room_states: dict[str, dict] = field(default_factory=dict)
    npc_states: dict[str, dict] = field(default_factory=dict)
    flags: dict[str, bool] = field(default_factory=dict)


class Command:
    def __init__(self, verb: str, args: list[str]):
        self.verb = verb
        self.args = args

    @classmethod
    def parse(cls, raw: str) -> Optional["Command"]:
        if not raw.strip():
            return None
        parts = raw.strip().split()
        if not parts:
            return None
        verb = parts[0].lower()
        args = parts[1:] if len(parts) > 1 else []
        return cls(verb, args)

    def __repr__(self) -> str:
        return f"Command(verb='{self.verb}', args={self.args})"
