from models import Room, Item, NPC, GameState, Command


def describe_room(room: Room, game_state: GameState) -> str:
    """Generate a descriptive string for a room based on its properties and current state."""
    lines = [f"{room.name}", "=" * len(room.name), room.description]

    # Add items in the room if any exist
    if room.items:
        items_in_room = []
        for item_id in room.items:
            # Try to find item details in room_states if available, otherwise assume default
            item_state = game_state.room_states.get(room.id, {}).get(item_id, {})
            if item_state.get("hidden", False):
                continue
            items_in_room.append(item_id)

        if items_in_room:
            lines.append("")
            lines.append("You see:")
            for item_id in items_in_room:
                # For now, assume items are referenced by ID — in a real implementation, we'd look up the full Item object
                lines.append(f"- {item_id}")

    # Add NPCs in the room if any exist
    if room.npcs:
        npcs_in_room = []
        for npc_id in room.npcs:
            npc_state = game_state.npc_states.get(npc_id, {})
            if npc_state.get("hidden", False):
                continue
            npcs_in_room.append(npc_id)

        if npcs_in_room:
            lines.append("")
            lines.append("You see:")
            for npc_id in npcs_in_room:
                lines.append(f"- {npc_id}")

    # Add connections
    if room.connections:
        lines.append("")
        lines.append("Exits:")
        for direction, target_room_id in room.connections.items():
            lines.append(f"- {direction} → {target_room_id}")

    return "\n".join(lines)


def describe_item(item: Item, game_state: GameState) -> str:
    """Generate a descriptive string for an item."""
    lines = [f"{item.name}", "-" * len(item.name), item.description]

    if not item.can_take:
        lines.append("")
        lines.append("(It cannot be taken.)")

    return "\n".join(lines)


def describe_npc(npc: NPC, game_state: GameState) -> str:
    """Generate a descriptive string for an NPC."""
    lines = [f"{npc.name}", "-" * len(npc.name), npc.description]

    # Add initial state info if present
    npc_state = game_state.npc_states.get(npc.id, {})
    if npc_state:
        lines.append("")
        lines.append("Current state:")
        for key, value in npc_state.items():
            lines.append(f"- {key}: {value}")

    return "\n".join(lines)


def generate_response(command: Command, game_state: GameState) -> str:
    """Generate a response string based on the parsed command and current game state."""
    verb = command.verb.lower()
    args = command.args

    if verb in ("look", "l"):
        if not args:
            # Look at current room
            room = Room(
                id=game_state.player_location,
                name="Unknown Room",
                description="No description available.",
                connections={}
            )
            # In a real implementation, we'd fetch the actual room from game state or world data
            return describe_room(room, game_state)
        elif len(args) == 1:
            target = args[0]
            # Look at specific item or NPC
            # For now, return placeholder
            return f"You look at {target}, but there's no description available yet."
        else:
            return "I don't understand that command."

    elif verb in ("go", "move", "walk"):
        if not args:
            return "Go where?"
        direction = args[0].lower()
        # In a real implementation, we'd check if the direction is valid for the current room
        return f"You try to go {direction}, but that path isn't available yet."

    elif verb in ("take", "grab", "pickup"):
        if not args:
            return "Take what?"
        item_id = " ".join(args)
        return f"You attempt to take {item_id}, but that feature isn't implemented yet."

    elif verb in ("inventory", "i"):
        if game_state.inventory:
            return "You are carrying:\n" + "\n".join(f"- {item}" for item in game_state.inventory)
        else:
            return "You are not carrying anything."

    elif verb in ("help", "?"):
        return (
            "Available commands:\n"
            "- look [item|npc]\n"
            "- go <direction>\n"
            "- take <item>\n"
            "- inventory\n"
            "- quit"
        )

    elif verb in ("quit", "q"):
        return "Thanks for playing!"

    else:
        return f"I don't understand '{verb}'. Type 'help' for available commands."
