from typing import Optional
from models import GameState, Command
from parser import parse_command
from loader import load_world_data, save_game_state


class GameEngine:
    """Core game engine managing state, command processing, and game loop."""

    def __init__(self, world_data: Optional[dict] = None):
        """Initialize the game engine with optional world data."""
        self.game_state = GameState(player_location="start")
        self.rooms = []
        self.items = []
        self.npcs = []

        if world_data:
            self.rooms, self.items, self.npcs = load_world_data(world_data)

        # Command dispatcher mapping verbs to handler methods
        self.command_handlers = {
            "look": self.handle_look,
            "go": self.handle_move,
            "take": self.handle_take,
            "inventory": self.handle_inventory,
            "use": self.handle_use,
            "save": self.handle_save,
            "quit": self.handle_quit,
        }

        self.valid_verbs = set(self.command_handlers.keys())
        self.running = True

    def process_command(self, raw_input: str) -> str:
        """Process a raw command string and return response text."""
        command = parse_command(raw_input)
        if command is None:
            return "I didn't understand that."

        # Validate command verb
        if command.verb not in self.valid_verbs:
            return f"Unknown command: {command.verb}"

        # Execute handler and return response
        handler = self.command_handlers.get(command.verb)
        if handler:
            return handler(command)
        return "That command is not implemented yet."

    def handle_look(self, command: Command) -> str:
        """Handle the 'look' command to describe the current room."""
        # Find current room
        current_room = None
        for room in self.rooms:
            if room.id == self.game_state.player_location:
                current_room = room
                break

        if current_room is None:
            return "You're in an undefined location."

        # Build description
        lines = [f"You are in {current_room.name}."]
        lines.append(current_room.description)

        # List items
        if current_room.items:
            item_names = []
            for item_id in current_room.items:
                for item in self.items:
                    if item.id == item_id:
                        item_names.append(item.name)
                        break
            lines.append(f"You see: {', '.join(item_names)}.")

        # List NPCs
        if current_room.npcs:
            npc_names = []
            for npc_id in current_room.npcs:
                for npc in self.npcs:
                    if npc.id == npc_id:
                        npc_names.append(npc.name)
                        break
            lines.append(f"Here are: {', '.join(npc_names)}.")

        # List connections
        if current_room.connections:
            connections = [direction for direction in current_room.connections.keys()]
            lines.append(f"Exits: {', '.join(connections)}.")

        return "\n".join(lines)

    def handle_move(self, command: Command) -> str:
        """Handle movement commands like 'go north'."""
        if not command.args:
            return "Go where?"

        direction = command.args[0].lower()
        current_room = None

        # Find current room
        for room in self.rooms:
            if room.id == self.game_state.player_location:
                current_room = room
                break

        if current_room is None:
            return "You're in an undefined location."

        # Check if direction is valid
        if direction not in current_room.connections:
            return f"You can't go {direction} from here."

        # Move to new room
        new_room_id = current_room.connections[direction]
        self.game_state.player_location = new_room_id
        return f"You go {direction} to {new_room_id}."

    def handle_take(self, command: Command) -> str:
        """Handle taking items with 'take item'."""
        if not command.args:
            return "Take what?"

        item_name = " ".join(command.args).lower()
        current_room = None

        # Find current room
        for room in self.rooms:
            if room.id == self.game_state.player_location:
                current_room = room
                break

        if current_room is None:
            return "You're in an undefined location."

        # Find item by name
        item_to_take = None
        for item_id in current_room.items:
            for item in self.items:
                if item.id == item_id and item.name.lower() == item_name:
                    item_to_take = item
                    break
            if item_to_take:
                break

        if item_to_take is None:
            return f"You don't see {item_name} here."

        if not item_to_take.can_take:
            return f"You can't take {item_to_take.name}."

        # Add to inventory and remove from room
        self.game_state.inventory.append(item_to_take.id)
        current_room.items.remove(item_to_take.id)
        return f"You picked up {item_to_take.name}."

    def handle_inventory(self, command: Command) -> str:
        """Display player's inventory."""
        if not self.game_state.inventory:
            return "Your inventory is empty."

        item_names = []
        for item_id in self.game_state.inventory:
            for item in self.items:
                if item.id == item_id:
                    item_names.append(item.name)
                    break

        return f"Inventory: {', '.join(item_names) if item_names else 'empty'}."

    def handle_use(self, command: Command) -> str:
        """Handle using items (placeholder for future functionality)."""
        if not command.args:
            return "Use what?"
        return "You can't use that yet."

    def handle_save(self, command: Command) -> str:
        """Save game state to file."""
        try:
            save_game_state(self.game_state, "game_state.json")
            return "Game saved successfully."
        except Exception as e:
            return f"Failed to save game: {str(e)}"

    def handle_quit(self, command: Command) -> str:
        """Handle quit command to exit the game."""
        self.running = False
        return "Goodbye!"

    def run(self) -> None:
        """Main game loop for interactive play."""
        print("Welcome to the game! Type 'quit' to exit.")
        print(self.handle_look(Command("look", [])))

        while self.running:
            try:
                raw_input = input("> ").strip()
                if not raw_input:
                    continue
                response = self.process_command(raw_input)
                print(response)
                if not self.running:
                    break
            except EOFError:
                break
            except KeyboardInterrupt:
                print("\nGoodbye!")
                break
