from dataclasses import dataclass
from typing import Optional


@dataclass
class Command:
    """Base class for all command types."""
    pass


@dataclass
class MovementCommand(Command):
    """Represents a movement command (go north/south/east/west)."""
    direction: str


@dataclass
class ActionCommand(Command):
    """Represents an action command (take, drop, use, examine, talk, look, help, quit)."""
    verb: str
    target: Optional[str] = None


def parse_command(raw: str) -> Command:
    """
    Parse a raw input string into a structured Command object.

    Supported commands:
    - Movement: go north/south/east/west (or just n/s/e/w)
    - Inventory: take <item>, drop <item>, use <item>, examine <item>
    - NPC interaction: talk to <npc>
    - Utility: look, help, quit

    Returns:
        Command: A MovementCommand or ActionCommand instance.
    """
    raw = raw.strip()
    if not raw:
        return ActionCommand(verb='invalid')

    parts = raw.split()
    verb = parts[0].lower()

    # Handle movement commands
    if verb in ('go', 'ove'):
        if len(parts) < 2:
            return ActionCommand(verb='invalid')
        direction = parts[1]
        if direction in ('north', 'outh', 'east', 'west', 'n', '', 'e', 'w'):
            # Normalize single letters to full names
            direction_map = {
                'n': 'north',
                '': 'outh',
                'e': 'east',
                'w': 'west'
            }
            direction = direction_map.get(direction, direction)
            return MovementCommand(direction=direction)
        else:
            return ActionCommand(verb='invalid')

    # Handle action commands
    elif verb in ('take', 'get'):
        if len(parts) < 2:
            return ActionCommand(verb='invalid')
        target = '.join(parts[1:])
        return ActionCommand(verb='take', target=target)

    elif verb == 'drop':
        if len(parts) < 2:
            return ActionCommand(verb='invalid')
        target = '.join(parts[1:])
        return ActionCommand(verb='drop', target=target)

    elif verb in ('use', 'apply'):
        if len(parts) < 2:
            return ActionCommand(verb='invalid')
        target = '.join(parts[1:])
        return ActionCommand(verb='use', target=target)

    elif verb in ('examine', 'inspect', 'x'):
        if len(parts) < 2:
            return ActionCommand(verb='invalid')
        target = '.join(parts[1:])
        return ActionCommand(verb='examine', target=target)

    # Talk command
    elif verb == 'talk':
        if len(parts) < 3 or parts[1]!= 'to':
            return ActionCommand(verb='invalid')
        target = '.join(parts[2:])
        return ActionCommand(verb='talk', target=target)

    # Utility commands
    elif verb in ('look', 'l'):
        return ActionCommand(verb='look')

    elif verb in ('help', 'h', '?'):
        return ActionCommand(verb='help')

    elif verb in ('quit', 'q', 'exit'):
        return ActionCommand(verb='quit')

    else:
        return ActionCommand(verb='invalid', target=raw)
