```python
"""YAML file loading and validation for world data."""

import yaml
from typing import Dict, List, Any

from models import Room, Item, NPC, WorldData, Direction, DialogueNode


def validate_world(data: Dict[str, Any]) -> None:
    """Validate the structure of world data loaded from YAML.

    Args:
        data: Dictionary containing world data from YAML file.

    Raises:
        ValueError: If the data structure is invalid or required fields are missing.
    """
    if not isinstance(data, dict):
        raise ValueError("World data must be a dictionary")

    # Validate rooms
    if "rooms" not in data:
        raise ValueError("Missing required key: 'rooms'")

    if not isinstance(data["rooms"], list):
        raise ValueError("'rooms' must be a list")

    for room in data["rooms"]:
        if not isinstance(room, dict):
            raise ValueError("Each room must be a dictionary")

        required_room_fields = ["id", "name", "description"]
        for field in required_room_fields:
            if field not in room:
                raise ValueError(f"Room missing required field: '{field}'")

        if not isinstance(room.get("connections"), dict):
            raise ValueError("Room 'connections' must be a dictionary")

        if not isinstance(room.get("items"), list):
            raise ValueError("Room 'items' must be a list")

        if not isinstance(room.get("npcs"), list):
            raise ValueError("Room 'npcs' must be a list")

    # Validate items
    if "items" not in data:
        raise ValueError("Missing required key: 'items'")

    if not isinstance(data["items"], list):
        raise ValueError("'items' must be a list")

    for item in data["items"]:
        if not isinstance(item, dict):
            raise ValueError("Each item must be a dictionary")

        required_item_fields = ["id", "name", "description"]
        for field in required_item_fields:
            if field not in item:
                raise ValueError(f"Item missing required field: '{field}'")

    # Validate NPCs
    if "npcs" not in data:
        raise ValueError("Missing required key: 'npcs'")

    if not isinstance(data["npcs"], list):
        raise ValueError("'npcs' must be a list")

    for npc in data["npcs"]:
        if not isinstance(npc, dict):
            raise ValueError("Each NPC must be a dictionary")

        required_npc_fields = ["id", "name", "description"]
        for field in required_npc_fields:
            if field not in npc:
                raise ValueError(f"NPC missing required field: '{field}'")

        if "dialogue" in npc and not isinstance(npc["dialogue"], dict):
            raise ValueError("NPC 'dialogue' must be a dictionary")


def load_world(filepath: str) -> WorldData:
    """Load and parse world data from a YAML file.

    Args:
        filepath: Path to the YAML file containing world data.

    Returns:
        WorldData: Populated WorldData object with rooms, items, and NPCs.

    Raises:
        FileNotFoundError: If the YAML file does not exist.
        yaml.YAMLError: If the YAML file is malformed.
        ValueError: If the data structure is invalid.
    """
    with open(filepath, "r", encoding="utf-8") as f:
        data = yaml.safe_load(f)

    validate_world(data)

    # Build rooms dictionary
    rooms: Dict[str, Room] = {}
    for room_data in data["rooms"]:
        connections: Dict[Direction, str] = {}
        for direction_str, room_id in room_data.get("connections", {}).items():
            direction = Direction(direction_str)
            connections[direction] = room_id

        room = Room(
            id=room_data["id"],
            name=room_data["name"],
            description=room_data["description"],
            connections=connections,
            items=list(room_data.get("items", [])),
            npcs=list(room_data.get("npcs", []))
        )
        rooms[room.id] = room

    # Build items dictionary
    items: Dict[str, Item] = {}
    for item_data in data["items"]:
        item = Item(
            id=item_data["id"],
            name=item_data["name"],
            description=item_data["description"],
            usable=item_data.get("usable", False),
            effect=item_data.get("effect", "")
        )
        items[item.id] = item

    # Build NPCs dictionary
    npcs: Dict[str, NPC] = {}
    for npc_data in data["npcs"]:
        dialogue: Dict[str, List[DialogueNode]] = {}
        if "dialogue" in npc_data:
            for topic, responses in npc_data["dialogue"].items():
                dialogue_nodes: List[DialogueNode] = []
                for response in responses:
                    if isinstance(response, dict):
                        dialogue_nodes.append(
                            DialogueNode(
                                response=response.get("response", ""),
                                conditions=response.get("conditions", {}),
                                choices=response.get("choices", {})
                            )
                        )
                    else:
                        dialogue_nodes.append(
                            DialogueNode(response=str(response))
                        )
                dialogue[topic] = dialogue_nodes

        npc = NPC(
            id=npc_data["id"],
            name=npc_data["name"],
            description=npc_data["description"],
            dialogue=dialogue
        )
        npcs[npc.id] = npc

    return WorldData(rooms=rooms, items=items, npcs=npcs)
